    for refs, mpn, part, rating, applied, margin in [
        (('U7',), 'SC189ASKTRT', 'U7 SC189ASKTRT, VCC1V0 (2026-11-20)', 'VIN 2.9-5.5 V (abs max 6 V), 1.5 A, Tj -40..125 C; UVLO 2.60-2.80 V rising, 250 mV hysteresis (SC189 datasheet)', f'VIN and EN on VU, the LTC3556 VOUT: 3.4-4.7 V while USB is present and the load fits its input budget ({USB_LIM} from VBUS, docs/ltc3556.md); beyond that budget, and on battery alone, VU is the cell minus the internal ideal diode, about 2.8 V at a 3.0 V cell and 1 A. VCC1V0 load 19 mA (empty design) to 1.04 A (heavy design), Vivado estimates (docs/ltc3556.md)', 'OK while VU is above 2.9 V; near the end of discharge VU can sit just under the 2.9 V operating minimum while still above UVLO. Tj not re-estimated for the 1.0 V rail'),
        (('L3',), 'DFE252010P-1R5M=P2', 'L3 DFE252010P-1R5M, U7 (2026-11-20)', 'Isat 2.1 A, Idc 1.8 A (40 C rise)', 'about 1.2 A peak at a 1 A VCC1V0 load (docs/ltc3556.md)', 'OK, 57 % of Isat'),
        (('L1', 'L2', 'L9'), 'DFE252012F-2R2M=P2', 'L1, L2, L9 DFE252012F-2R2M: LTC3556 buck-boost, Buck2, Buck1 (2026-11-20)', 'Isat 3.3 A, Itemp 2.3 A, DCR 82 mOhm max (the lower of two distributor listings, docs/ltc3556.md)', 'L1 about 0.9 A peak at the 0.66 A worst-case VCC3V3 load from a 3.0 V cell (0.81 A input plus about 0.1 A half-ripple, docs/ltc3556.md), and up to the buck-boost switch limit (2 A minimum, ILIMF3 3 A maximum) in overload; L2 about 0.19 A peak at 77 mA on VCC1V8; L9 on Buck1, which runs unloaded as a sequencing slot', 'OK in operation; in overload L1 can reach the 3 A ILIMF3 maximum, only 10 % under its 3.3 A Isat; confirm the ratings on Murata\'s own datasheet (docs/ltc3556.md)'),
        (('L8',), 'DFE252012F-3R3M=P2', 'L8 DFE252012F-3R3M, LTC3556 PowerPath (2026-11-20)', 'Isat 2.5 A, Itemp 1.8 A, DCR 0.135 ohm max (the lower of two distributor listings, docs/ltc3556.md)', 'about 0.71 A peak at the USB input limit; the PowerPath switch limit is 2 A typical, with no maximum given (docs/ltc3556.md)', 'OK, Isat above the 2 A typical switch limit'),
        (('U8',), 'LTC3556EUFD#PBF', 'U8 LTC3556EUFD#PBF (2026-11-20)', 'VBUS 4.35-5.5 V (7 V transient abs max); VOUT 3.4 V min, BAT + 0.3 V, 4.7 V max; Buck1 400 mA; buck-boost about 1 A (switch-A limit 2 A min); 110 C die thermal regulation; thetaJA 37 C/W (docs/ltc3556.md)', f'USB 5.25 V max; input limit {USB_LIM} (R103 576 ohm, the 7 mA IVBUSQ included); charge 248 mA (R102 4.12k); VCC3V3 about 340 mA typical, 650 mA worst case; VCC1V8 49-77 mA; Buck1 unloaded (VCC1V0 is on U7); IC loss 0.6 W maximum = 22 C rise, estimated while Buck1 still carried VCC1V0 (docs/ltc3556.md)', 'OK; measure VBUS hot-plug ringing against the 7 V transient abs max at bring-up (docs/ltc3556.md)'),
        (('X4',), 'S2B-PH-SM4-TB(LF)(SN)', 'X4 JST PH S2B-PH-SM4-TB (2026-11-20)', '2 A per contact (AWG #24), 100 V (JST PH datasheet)', 'charge 248 mA (R102); battery discharge about 1.0 A at a 3.0 V cell, about 1.2 A for a heavy FPGA design on battery (docs/ltc3556.md)', 'OK, 60 % of the contact rating at 1.2 A'),
        (('Q2',), '2N7002LT1G', 'Q2 2N7002', '60 V, 115 mA (onsemi), VGS +-20 V', '3.3 V, 1.8 mA LED current, 3.3 V gate', 'OK'),
        (('U1',), 'XC7A35T-2CPG236I', 'U1 XC7A35T-2CPG236I (2026-11-20)', 'VCCINT 0.95-1.05, VCCAUX 1.71-1.89, VCCO 3.135-3.465 V, Tj -40-100 C (DS181 Table 2)',
         f'VCC1V0 from U7 SC189A, +-2.5 % plus +-1 % load: 0.965-1.035 V; VCC1V8 from the LTC3556 Buck2: {v18[3]:.3f}-{v18[4]:.3f} V; VCC3V3 from the LTC3556 buck-boost: {v33[0]:.2f} V nominal (R115 324k, R116 102k), {v33[1]:.3f}-{v33[2]:.3f} V over the 0.78-0.82 V feedback band with 1 % resistors, {v33[3]:.3f}-{v33[4]:.3f} V adding a +-50 nA FB bias current (docs/ltc3556.md); Tj rise 10-15 C',
         f'OK at nominal; VCCINT has 15 mV of the 50 mV band left for ripple and drop, keep the 1.0 V path short. VCC1V8 stays inside 1.71-1.89 V at every corner. VCC3V3\'s top corner, every tolerance at its limit together, is {(v33[2] - VCCO_MAX) * 1000:.0f} mV over the {VCCO_MAX} V VCCO maximum from the reference and resistors alone and {(v33[4] - VCCO_MAX) * 1000:.0f} mV over with the bias current: statistically unlikely; 0.5 % divider resistors would bring it to {v33_half[2]:.3f} V ({v33_half[4]:.3f} V with the bias current)'),
        (('U2',), 'FT2232HQ-REEL', 'U2 FT2232HQ (2026-11-20)', 'VCCIO 3.0-3.6 V, clock 12 MHz +-30 ppm, Tj 125 C', '3.3 V; ECS-3225SMV-120-FP-TR is +-10 ppm incl. aging; QFN thetaJA 29.67 C/W, thetaJC 14.12 C/W (DS_FT2232H table 5.7; the FT2232HL was 37.66 C/W)', 'OK'),
        (('U3',), 'AS4C32M16SB-7TCN', 'U3 AS4C32M16SB-7TCN', 'VDD 3.0-3.6 V, 143 MHz at CL3 (100 MHz at CL2), TA 0..70 C', '3.3 V; commercial ambient range, now the narrowest on the board (U1 is the industrial -2I since 2026-10-23)', 'OK; the controller must use the -7 column (tRCD/tRP 21 ns, tRC 63 ns, tWR 14 ns) and CL3 above 100 MHz'),
        (('U4',), 'W25Q128JVSIQ', 'U4 W25Q128JVSIQ', '2.7-3.6 V, 133 MHz', '3.3 V, CCLK a few tens of MHz', 'OK'),
        (('X1',), '105017-0001', 'X1 105017-0001 (2026-11-20)', '1.8 A per power contact (VBUS, GND), 1.0 A per signal contact, 30 V (Molex 105017 product data)', f'VBUS: the LTC3556 input limit, {USB_LIM} (R103 576 ohm, the 7 mA IVBUSQ included, docs/ltc3556.md)', 'OK, 28 % of the VBUS contact rating at the top of the spread (49.6 % even against the 1.0 A signal-contact figure)'),
        (('X2',), None, 'X2 header' + (' / J1 Pmod' if 'J1' in comps else '') + ' (2026-11-20)', '0.1 in pins ~1-3 A', 'VU on X2-22 (the LTC3556 PowerPath output, to be used as an output only, docs/ltc3556.md), VCC3V3 / VCC1V8 / VCC1V0 on X2-18..20' + (', VCC3V3 on J1-6/12' if 'J1' in comps else ''), 'OK'),
        (('LD0', 'LD1', 'LD2', 'LD3', 'LD4'), None, 'LEDs (2026-11-20)', 'IF 25 mA (Everlight 19-337, the same table as the VS NRD8), 20-30 mA (LTST)',
         f'LD0 red about 3.9 mA (330 ohm; {I_RED * 1000:.1f} mA at the 1.7 V VF corner); LD0 blue/green, VF 2.7-3.8 V at 20 mA (assembly BOM), through 33 ohm up to about {I_BG * 1000:.0f} mA at the 2.7 V VF corner before the FPGA driver\'s own drop, which limits it; LD1/LD2 about 4 mA; LD3 1.8-2.1 mA (R107 680R from VCC3V3, shunted by PGOODALL), LD4 1.3-2.6 mA (R108 1.0k from VU, sunk by CHRG) (docs/ltc3556.md)',
         f'OK; the blue/green corner ({I_BG * 1000:.0f} mA) is close to the 25 mA IF maximum and is reached only if the FPGA driver drops nothing'),
        (('U1',), None, 'FPGA I/O driving LEDs (2026-11-20)', '12 mA default LVCMOS33 drive',
         f'sinks LD0\'s three cathodes: red about 3.9 mA; blue/green up to about {I_BG * 1000:.0f} mA through 33 ohm at the 2.7 V VF corner, so set by the driver rather than the resistor; sources LD1/LD2 through 330 ohm, about 4 mA',
         'OK for red and LD1/LD2; the blue/green sink current is driver-limited at the low-VF corner and can exceed the 12 mA nominal drive'),
    ]:
        if not any(r in comps for r in refs): continue      # the part left the board
        w(f'| {part}{stale(refs, mpn)} | {rating} | {applied} | {margin} |')
    # --- findings
    w('\n## 6. Findings\n')
    w('Dated history: each finding stands as written on its date. Where a present-tense statement in one is no longer true '
      f'of the board, a dated note follows it (or, for a finding that was superseded as a whole, also precedes it).\n')
    findings = [   # dated history; do not rewrite, add a note below instead
        '**U10 sat on a footprint the part cannot solder to. FIXED 2026-09-10.** The imported package SOIC8 is a 300-mil pattern with its pad rows 7.62 mm apart, so its lands began 3.06 mm out from the centreline while the 93LC46BT-I/SN (SN = the 3.90 mm narrow body, 6.00 mm BSC lead span) stops its lead tips at 3.00 mm -- 0.06 mm of air, no overlap at all. Open since the 2026-09-07 audit with two ways out: change the land, or order the 208-mil SOIJ part 93LC46BT-I/SM to suit the pads. The land changed. SPI-8_SOIC_150 was copied into the PcbLib from zulu_a7.sch on 2026-09-10 for exactly this, and tools/u10_narrow_soic.py repoints U10\'s model record at it -- one record rewritten in place, no index shifts, but the footprint name appears TWICE in a RECORD=45 (ModelName and ModelDatafileEntity0) and both have to move. Netlist after: 182 components, 179 nets and 795 pads all unchanged, with U10\'s footprint field the only difference in the file. No SOIC8 reference is left in the schematic.',
        '**The SOD123 pattern is no longer used.** D1 went with the bq24232 and D2/D3 went with the +5V-INPUT pin, both on 2026-09-09 (the LiPo on X4 is the external supply), so the SOD323F / SOD-123FL land mismatch found on 2026-09-07 needs no correction; no diode remains on the board.',
        '**CPG236 lands are 0.225 mm on purpose, not by mistake.** They were briefly raised to UG475\'s 0.275 mm on 2026-09-10 on the reading that Table A-1 asks for it. It does not: 0.275 mm is the MAXIMUM PCB solder land for CPG, and the 1:1 reliability recommendation points at that same maximum. Taking it makes the board unroutable. At 0.5 mm pitch the inter-land gap is 0.5 minus the land, and rings 1 and 2 must cross a populated row to reach the depopulated annulus whichever way they leave, so a 3 mil trace at 3.5 mil clearance (0.0762 + 2 x 0.09 = 0.2562 mm) has to fit through it. At a 0.225 mm land the gap is 0.275 mm and the margin is +0.0188 mm; at 0.275 mm the gap is 0.225 mm and the margin is -0.0312 mm. No layer count fixes that -- only via-in-pad HDI would, and PCBWay declined HDI in writing on 2026-08-27. The change was reverted the same day: the library carries 0.225 mm and tools/verify_pcblib.py asserts it. The trade is a 0.82:1 land against AMD\'s 1:1 board-level-reliability recommendation, and it had already been made deliberately in board/STACKUP.md on 2026-08-30. Still to set as an Altium rule: solder-mask expansion, 0.05 mm per side.',
        '**The PCB footprint library now exists. DONE 2026-09-10.** There had been no PcbLib, PcbDoc or SchLib anywhere in the repo, so all 28 footprints the schematic names resolved to nothing -- not just the ones on the missing list. 19 were already drawn, in the <libraries> section of the old EAGLE board, so tools/make_fp_source.py patches a throwaway copy of that .brd and Altium converts it (Import Wizard, then Design > Make PCB Library). The old board is read for its library section only; its placement, routing, stack and rules are discarded with the scratch project. Corrected on the way through: ZULU-DIP37 to 40 pads, the CPG236 lands, SPI-8_SOIC_150 copied in from the .sch for U10, and EVERLIGHT-19-337 as the VS-NRD8 pattern renumbered. The eight with no geometry anywhere -- 742C043, 742C163, DM3D-SF, FT2232HL-LQFP64, JST-B2B-PH-SM4-TB, PTS810, SOT23-5, VQFN16-3X3-RGT -- were then drawn from the makers land patterns: each was read out of the datasheet by one agent and re-derived from the same primary source by a second told to refute it, giving six CONFIRMED, one CORRECTED and none rejected (docs/footprint_lands.md carries every number and its citation). Only FT2232HL-LQFP64 is derived rather than published -- FTDI print no land at all -- and it follows IPC-7351B density level B. tools/verify_pcblib.py reads the saved PcbLib back through its OLE storages and checks all 41 patterns against the source geometry, pad name by pad name. The library was added to zulu_a7.PrjPcb on 2026-09-10 and now shows under Libraries in the Projects panel ([Document8] in the project file). Remaining Altium-side work, both of them rules rather than geometry because EAGLE keeps them in the DRC: the CPG236 mask expansion (0.05 mm per side on the 0.225 mm land) and the bq24232 thermal pad paste reduction to 1.55 mm with 0.07 mm mask expansion on pads 1-16.',
        '**Oscillator grade is out of the FT2232H spec.** ASEM1-12.000MHZ-LC-T decodes (datasheet p3) to 3.3 V, -40..85 C, +-50 ppm; the FT2232H datasheet asks for +-30 ppm. The comment on Q1 says 25 ppm, so the intent was the LR grade (ASEM1-12.000MHZ-LR-T), which no distributor stocks. A 20-agent search on 2026-09-08 (Digi-Key plus the makers\' datasheets, top picks cross-examined) found four pin-compatible 3.2 x 2.5 mm parts on Digi-Key\'s shelf that meet +-30 ppm all-inclusive: ECS-3225SMV-120-FP-TR (+-10 ppm including aging, -40..105 C, 1,830 pcs, $2.90, recommended), Abracon ASEMB-12.000MHZ-LY-T (+-10 ppm plus 5 ppm/yr aging, 6,143 pcs, $4.40), ECS-3225SMVQ-120-DS-TR (+-20 ppm including aging, 862 pcs, $1.82) and SiTime SIT1602BI-22-33E-12.000000 (+-25 ppm including first-year aging, 440 pcs, $1.54). The SiTime SiT8008 grades that a judge preferred are factory stock programmed to order, not shelf stock. Applied on 2026-09-08 at the user\'s choice: Q1 is now ECS-3225SMV-120-FP-TR (comment 12MHz 10ppm), same 3225 land, pin 1 tied high runs the oscillator.',
        '**Three parts were obsolete** and were replaced on 2026-09-07 by tools/apply_bom_substitutions.py: R34 742C083472JTR by 742C083472JP, the 10 uF 10 V 0805 GRM21BR61A106KE19L on C78/C147-C149 by Samsung CL21A106KPFNNNG, and the 4.7 uF GRM188R61A475KE15D on eleven decoupling positions. The first 4.7 uF replacement (GRM188R61A475KAAJD) turned out to be NRND at Murata, and every 4.7 uF 10 V X5R 0603 on the market is NRND, obsolete or dry, so on 2026-09-08 those eleven positions moved to the 16 V grade GRM188R61C475KE11D, which Murata lists as in production and which also halves the DC-bias loss on the 3.3 V positions.',
        '**Three part numbers were unknown to the distributor**; two were replaced on 2026-09-07 (GRM033R60J474KE15D, a typo, by GRM033R60J474KE90D on 22 positions; GRM155R61C474KA88D on C124 by Samsung CL05A474KO5NNNC) and the 22 uF 0603 on C82/C84 moved to the stocked 10 V Samsung CL10A226MP8NUNE. GRM155R60J335ME15D (C39/C139, the FT2232H VCORE filter, FTDI minimum 3.3 uF) is unobtainable and no 3.3 uF 0402 at 6.3 V or more exists that is not obsolete or NRND (Digi-Key\'s whole 3.3 uF 0402 list was checked on 2026-09-08). The same-footprint answer is 4.7 uF: Taiyo Yuden JMK105BBJ475MV-F, ordered under its new number MSASJ105BB5475MFNA01 (6.3 V X5R, 0.65 mm max, about 3.7 uF left at 1.8 V, 1.6 M pcs, $0.13, recommended), or Murata GRM155R60J475ME47D (0.60 mm max, in production, 980 k pcs, $0.10, but only about 2.2-2.8 uF left at 1.8 V so the pair sits close to FTDI\'s minimum at the tolerance corners). Both survived two skeptics each. Applied on 2026-09-08: C39 and C139 are now 4.7 uF MSASJ105BB5475MFNA01 (Digi-Key alias JMK105BBJ475MV-F).',
        '**No part is without a distributor any more**: the PTA-142 button became the C&K PTS810SJM250SMTR LFS and the Victory VS NRD8 RGB LED became the Everlight EAST1616RGBA8 (its pad-for-pad twin, pins renumbered) and the X2 ZULU-CONN pin field got its Sullins PRPC strips, all on 2026-09-08 (PRPC009/011 on the top row; the bottom row became 1x6 + 1x14 on 2026-09-09 after the LiPo landing was opened and the field renumbered 1-40). Only JP3/JP4 remain without a part, by design (bare holes).',
        '**Long-lead items** (2026-09-09; U2 has since gone back to the FT2232HQ, see finding 16): U2 became the FT2232HL on 2026-09-09 because the FT2232HQ has no authorized stock until April 2027; the HL is itself 0 at Digi-Key (1,000 due 19-Feb-2027) and only LCSC holds it (4,767), so name that channel or consign, the SDRAM -6 grade is dry until October 2026, so on 2026-09-08 U3 became the AS4C32M16SB-7TCN (same die, package and pinout, 143 MHz, commercial 0..70 C like the -1C FPGA; 1,478 at Digi-Key), and the 22 uF 0805 value (13 pcs) is dry across Murata, Samsung and TDK\'s active parts, with only NRND TDK stock; C82/C84 now carry the stocked Samsung CL10A226MP8NUNE.',
        '**C124 returned to the wrong ground. FIXED 2026-09-10.** C123 (100 nF) returned to GNDADC but C124 (470 nF) returned to digital GND, whereas UG480 Figure 6-1 draws both XADC supply filter capacitors from VCCADC to the analog ground on the far side of the ground ferrite L6. It put L6 inside the larger capacitor\'s decoupling loop and, with C123 in series, bridged GNDADC to GND at AC -- the one thing the two beads exist to prevent. The ground symbol at (535,222) on sheet 5 was already at the end of C124\'s own return wire, so tools/done_pullup_xadc_gnd.py renamed it GND -> GNDADC and it now draws as an analog ground. Netlist: GND 204 pads -> 203, GNDADC 7 -> 8, C124-2 the only pad that moved.',
        '**DONE readback sat on a divider, and the pull-up is now array elements. FIXED 2026-09-10.** Found by the Vivado I/O-planner audit, which is to say not by Vivado: it is invisible to the I/O planner, which stops at the package ball. R4-2 and R4-15 are the two ends of one element of the 100 R array, and the netlist read DONE = {R4-2, R100-1, U2-22} against FPGA-DONE = {R4-15, U1-U12} -- the 330 R pull-up and the FT2232H input on the SAME side of the series resistor and the FPGA\'s DONE ball on the other, so ADBUS5 read a divider midpoint rather than DONE. Unconfigured that is 3.3 x 100/430 = 0.767 V against the FT2232H\'s 0.80 V VIL max, 33 mV of margin before any tolerance is spent; the CTS 742C163 is +-5 %, so 105 R gives 0.797 V and 330 R at -5 % as well gives 0.828 V, which is over. A host tool could report DONE High with the part unconfigured. UG470 Figure 2-14 puts the pull-up at the ball and the series resistor between the ball and whatever watches it. R100 was first moved onto FPGA-DONE and then, on request, retired altogether: the pull-up is now R4G and R4H, the array\'s two spare elements, in series from VCC3V3 to FPGA-DONE and drawn on the FPGA-DONE row itself. In series rather than singly because one 100 R element across 3.3 V is 109 mW against the 742C163101JP\'s 63 mW per element -- 173 % of rating, held for as long as DONE is low, which is indefinitely if configuration never completes. Two in series is 27 mW each. The pull-up is 200 R, so DONE sinks 16.5 mA when low against 10 mA for the 330 R UG470 draws, and the discrete R100 leaves the BOM. Netlist: 183 components -> 182, 178 nets -> 179, 783 pads -> 785; FPGA-DONE = {R4-15, R4-7, U1-U12}, DONE = {R4-2, U2-22}, the series link its own net.',
        '**Two symbols still owned several pads per pin. FIXED 2026-09-10.** EAGLE lets one symbol pin own several package pads; the Altium importer collapses that into a single pin whose Designator is a comma list, which matches no footprint pad, so those pads would have arrived on the board unconnected. X3 was fixed this way on 2026-09-06 and these two were left, surfacing when the new library was checked against the symbols. BTN carried pins "1,2" and "3,4" against a four-pad PTS810 land, and X1 carried "5,MH1,MH2,MP1,MP2,MP3,MP4,MS1,MS2" against a thirteen-pad Molex land. tools/split_multipad_pins.py splits both: BTN becomes pads 1-4 with each new pad stubbed to its partner, X1 becomes nine pins on the right edge bussed to the GND port that already served pin 5. Netlist after: 182 components and 179 nets unchanged, 785 -> 795 pads, and exactly three nets touched -- GND gains X1-5 and the eight shell pads, VCC3V3 gains BTN-1/2, N$BTN gains BTN-3/4. No multi-pad pin remains on any sheet. The PTS810 land confirms the row-wise pairing this assumes: pads 1+2 are one terminal, 3+4 the other.',
        '**Everything else checks out**: the FPGA symbol and power tree, the FT2232H, SDRAM, flash and EEPROM pin functions, the USB receptacle, LED polarity and pads, capacitor voltage margins, resistor power, regulator and diode ratings. On 2026-09-08 nine of the findings and substitutions above were handed to independent reviewers told to refute them from primary sources; they confirmed all of the conclusions and corrected the details now written here (the D1/D2 land numbers, the D3 verdict, the 4.7 uF replacement, the 22 uF height, R34\'s concave terminations).',
        '**LiPo charger added 2026-09-09.** U8 (TI bq24232) replaces D1: USB5V0 into IN, OUT regulated at 4.4 V onto VU (VBAT - 60 mV on battery), battery on X4 (JST PH, pin 1 = +). The input is capped at 495 mA (R103), so the board can no longer exceed the USB limit; DPPM trims the 244 mA charge current (R102) first and the battery supplements peaks. On battery alone the 3.3 V buck holds regulation down to about 3.45 V. TS is a fixed 10 k (R106): the pack must carry its own protection. The +5V-INPUT pin with D2 and D3 was removed on 2026-09-09: the LiPo is the external supply. Scope battery-only start-up into the 40 uF on VU on the first board.',
        '**X2 pin field reworked 2026-09-09** for the LiPo header X4, which sits on the top side in the bottom row opposite the USB, the way X1 sits in the top row: +5V-INPUT (with D2/D3 and the VEXT net), GND5 and GND3 were removed, +3.3V2 and GND3 first swapped with CHAN12/CHAN13, then the bottom row was closed up and re-numbered by position: 21 GND, 22 VU, 23 RST#, 24 +3.3V, 25-27 CHAN14-16, 28-30 EMPTY (x 41.91 / 39.37 / 36.83, 10.16 mm between the neighbouring pin centres for the 7.95 mm JST body), then +3.3V2 as well, and the row was finally closed up and the whole field renumbered 1-40 straight through, skipping both landings the way the top row always has. The landing was then moved opposite the micro-USB and the top row put in channel order (1 GND, 2 CHAN-CLK, 3-9 CHAN0-6, 10-16 CHAN7-13, 17-20 the supplies). FINAL, the two rows mirror images: top row pins 1-9 (x 59.69..39.37), USB landing (36.83..29.21), pins 10-20 (26.67..1.27); bottom row pins 21-29 (21 GND, 22 VU, 23 RST#, 24-29 CHAN14-19), LiPo landing on the SAME four x values, pins 30-40 (CHAN20-28, ANALOG-IO0/1). Each landing is 12.70 mm between neighbouring pin centres and 11.176 mm clear, so the 7.95 mm JST body has 1.61 mm each side and X4 sits directly opposite the USB receptacle. Three grounds (1, 20, 21), 3.3 V on pin 17 alone. Strips: 1x9 + 1x11 in each row, two part numbers, two of each per board. THE ZULU-DIP37 FOOTPRINT MUST BE REDRAWN with 40 pads named 1-40: the imported one still names 44 and no longer matches above pin 26. Netlists checked at each step against the previous export: only the documented pad reassignments, nothing else.',
        '**U2 is the FT2232HQ again. DONE 2026-11-19.** The FT2232HL (LQFP-64, finding 9) needs more board depth than the QFN at the X2 pin 30/31 slot, so the side-entry LiPo connector X4 (JST S2B-PH-SM4-TB) fitted only with a PCB edge tab, which was dropped. U2 is back to the FT2232HQ-REEL (QFN-64 9 x 9 mm, the same device as the Cmod) at (30.50, 14.55) with X4 at (31.39, 4.90) and the board outline unchanged. Sheet 4 keeps pins 1-64 and has the grounded EP pin (tools/u2_ft2232hq.py; its footprint record names FT2232HQ-QFN64 in both ModelName and ModelDatafileEntity0, and tools/u2_model_entity.py repaired the saved sheet); the land is FT2232HQ-QFN64 in the PcbLib (tools/NoPmodU2Qfn.pas). Consequences: (a) the EP\'s in-pad vias are filled and capped (the fabrication notes), and its paste is a windowpane of nine 1.0 mm windows on a 1.25 mm pitch (51 % coverage) drawn in the GTP paste layer and called out in the assembly notes (reworded 2026-11-20); (b) sourcing is the long-lead problem finding 9 avoided: no FTDI-authorized stock until about Mar-Apr 2027 on 2026-11-16, and brokers are not acceptable because counterfeit FTDI parts exist; (c) thetaJA improves from 37.66 to 29.67 C/W. Section 2.2 and the tables above now describe the QFN. On Fab B Rev 2 the pad-net checks read the Protel netlist re-exported after the 2026-11-20 sync ECO (Project Outputs for zulu_a7_fab_b/zulu_a7_fab_b.NET).',
    ]
    # Fab B refresh 2026-11-20: dated notes, each printed only while the condition that makes it true holds.
    # finding number -> (superseded as a whole?, note)
    notes = {}
    u10 = comps.get('U10', {}); u10_fp = u10.get('fp')
    if u10_fp and u10_fp != 'SPI-8_SOIC_150':
        notes[1] = (True, f'Note 2026-11-20: U10 is now the {u10["params"].get("MANF#")} in MSOP-8 on {u10_fp} (sheet 4, docs/sync_schematics.md), '
                          'so the -I/SN SOIC part and SPI-8_SOIC_150 above are history.')
    no_diode = not any(re.fullmatch(r'D\d+', d) for d in comps)
    if 'VQFN16-3X3-RGT' not in by_fp:
        notes[2] = (False, 'Note 2026-11-20: the bq24232 itself left on 2026-11-10 (finding 14)'
                           + ('; there is still no diode on the board.' if no_diode else '.'))
    # Finding 3: read from the board on 2026-11-20 (PcbDoc md5 5fea1304, Rules6 stream, read-only) and the fabrication notes.
    notes[3] = (False, 'Note 2026-11-20: this board is a two-step sequential HDI build for PCBWay (fabrication notes, ORDER AND CAM GATE), '
                       'and 10 U1 lands carry a 0.30/0.15 mm Top-L2 laser microvia (L19, N17, N18, P17, P19, R18, T17, U12, U15, V13; '
                       'fabrication notes, BGA). The 0.05 mm per side mask expansion was not applied to U1: the PcbDoc (md5 5fea1304) carries '
                       'SolderMaskExpansion_U1 = 0 mm (InComponent(\'U1\'), priority 3, ahead of the board-wide 0.05 mm rule at priority 5), '
                       'and the fabrication notes ask PCBWay not to enlarge the U1 openings. board/STACKUP.md is at the repository root.')
    gone = [f for f in ('FT2232HL-LQFP64', 'JST-B2B-PH-SM4-TB', 'VQFN16-3X3-RGT', 'SPI-8_SOIC_150') if f not in by_fp]
    if gone:
        notes[4] = (False, f'Note 2026-11-20: {", ".join(gone)} are no longer used by any part'
                           + (', so the bq24232 paste and mask item above has lapsed (the bq24232 left on 2026-11-10)' if 'VQFN16-3X3-RGT' in gone else '')
                           + '; the CPG236 mask item is answered in the note to finding 3; the project library is now the 32-footprint '
                           'zulu_a7.PcbLib made from this board on 2026-11-20 (docs/sync_altium_steps.md).')
    if 'C39' not in comps and 'C139' in comps:
        notes[7] = (False, 'Note 2026-11-20: only C139 of the pair is on the sheets now.')
    if comps.get('X2', {}).get('params', {}).get('MANF#') == '4x PRPC010SAAN-RC':
        notes[8] = (False, 'Note 2026-11-20: since Rev 2 (2026-11-11) X2 is four 1x10 Sullins PRPC010SAAN-RC strips (docs/rev2_layout.md).')
    if (comps.get('U8', {}).get('params', {}).get('MANF#') or '').startswith('LTC3556'):
        notes[14] = (True, 'Superseded 2026-11-10 (docs/ltc3556.md): the bq24232 left together with U5 (by then a TPS63802) and U6. The LTC3556 '
                           '(U8, designator reused) is now the USB PowerPath, the charger and the VCC1V8 / VCC3V3 regulators, U7 SC189A keeps VCC1V0, '
                           + ('R104-R106 were deleted, ' if not any(r in comps for r in ('R104', 'R105', 'R106')) else '')
                           + 'R102 and R103 set the LTC3556 charge current and input limit, and VU is the LTC3556 VOUT. Section 2.2 checks its pins.')
    if padnet.get('X2-17') == 'GND' and padnet.get('X2-18') == 'VCC3V3':
        notes[15] = (True, 'Note 2026-11-20: ZULU-DIP37 was redrawn with 40 pads on 2026-09-10 (section 2.3); pins 17-20 became GND / +3.3V / +1.8V / +1.0V '
                           'on 2026-10-07; Rev 2 (2026-11-11) splits each row 10 + landing + 10, with X1 between pins 10 and 11 and X4 between pins 30 and 31 '
                           '(section 2.2, docs/rev2_layout.md).')
    if comps.get('U2', {}).get('fp') == 'FT2232HQ-QFN64':
        notes[16] = (False, 'Note 2026-11-20 (Fab B): the 2026-11-19 date and the edge-tab reason above are the no-PMOD board\'s. On this board '
                            'U2 was the FT2232HL until the 2026-11-20 sync, which changed U2 and X4 together (docs/sync_schematics.md, '
                            'docs/sync_altium_steps.md). Sheet 4 was changed by tools/u2_ft2232hq.py, which carries the ModelDatafileEntity0 fix; tools/u2_model_entity.py and '
                            'tools/NoPmodU2Qfn.pas are in Zulu_A7_no_pmod/Rev_2. The U2 and X4 positions above hold on this board too, and the EP\'s '
                            'GND ties are 10 in-pad laser microvias (fabrication/Zulu_A7_Fab_B_Rev_2_PCBWay_FAB_NOTES.txt).')
    for i, f in enumerate(findings, 1):
        sup, note = notes.get(i, (False, ''))
        w(f'{i}. ' + ('*(History: superseded; see the dated note at the end.)* ' if sup else '') + f + (f' *{note}*' if note else ''))
    print('\n'.join(out))

